import{z as l,x as s,o as a,c as C,q as n,j as o,D as B,d as A,s as t,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"碳边境调节","description":"","frontmatter":{"title":"碳边境调节","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/env-cbam.md","filePath":"econ/env-cbam.md","lastUpdated":1791063341000}'),D={name:"econ/env-cbam.md"};function d(p,E,c,F,m,h){const r=s("Mermaid");return a(),C("div",null,[E[2]||(E[2]=n('<h1 id="碳边境调节" tabindex="-1">碳边境调节 <a class="header-anchor" href="#碳边境调节" aria-label="Permalink to &quot;碳边境调节&quot;">​</a></h1><div class="epigraph"><p>碳价改不了物理，但能改选址：单边定价把排放推过国境，边境税试图让影子价格跟着货物过境。</p><footer>—— 据 Nordhaus, American Economic Review, 2015（气候俱乐部）与欧盟 CBAM 条例（2023/956）整理</footer></div><p><a href="/econ/env-power-markets">上一课</a>把市场边界画在联络线上，跨区靠耦合出清；碳政策的边界画在国境上就没这么干净——单边碳价只在本辖区有效，排放会从缺口迁走。<a href="/econ/pigouvian-carbon-price">庇古税与碳定价</a>的边界里点过一句「碳价管不住泄漏」，本课把泄漏通道数清，再写边境税这一装置的设计、原理与代价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>泄漏有三条通道。生产迁移：钢、水泥、铝、化肥这类碳密集品，贸易成本低于碳成本差，碳价使产地外迁——辖区排放降了，全球排放没降，只剩生产的地理重排。能源市场通道：单边碳价压低世界化石燃料的需求与价格，未覆盖辖区面对更便宜的燃料，反而烧得更多。投资通道：新产能的选址天然绕开碳价。三通道之外还有一层政治：贸易暴露产业要求对等保护，否则碳价在国内先站不住。缺口因此是：把影子碳价延伸到口岸，又不违反贸易规则、不把气候政策做成变相关税。</p><p><span class="marginnote">术语翻译：「嵌入式排放」就是一件货物从原料到成品一路上烧掉的碳的总和。比如高炉路线的一吨钢大约伴随 1.8 吨二氧化碳，这 1.8 吨就「嵌」在钢里；CBAM 要进口商为这些看不见的碳，按口岸碳价补一张门票。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>EU CBAM 的口径：进口商按嵌入式排放（申报或默认值）购买证书，证书价格锚定国内碳价的拍卖均价；原产地已付的碳价可抵扣；覆盖从钢、水泥、铝、化肥、电力、氢起步；与免费配额互斥——免费配额按计划退坡，两套防泄漏装置并存就是双重保护。设计轴有三问：排放怎么测（默认值防造假，但一刀切惩罚低碳出口商）；下游产品覆不覆盖（不覆盖则从下游进口即可绕开）；出口退不退税（不退，退税更近似出口补贴）。替代与互补的组织形式是碳俱乐部（Nordhaus 2015）：集团内互免、对外统一门槛，用贸易结构把参与变成占优策略。</p>',8)),(a(),o(i,null,{default:B(()=>[t(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E5%8D%95%E8%BE%B9%E7%A2%B3%E4%BB%B7%22%5D%20--%3E%20LEAK%5B%22%E6%B3%84%E6%BC%8F%3A%20%E8%BF%81%E7%A7%BB%2F%E8%83%BD%E6%BA%90%E5%B8%82%E5%9C%BA%2F%E6%8A%95%E8%B5%84%22%5D%0A%20%20DOM%20--%3E%20COMP%5B%22%E8%B4%B8%E6%98%93%E6%9A%B4%E9%9C%B2%E4%BA%A7%E4%B8%9A%E7%9A%84%E4%BF%9D%E6%8A%A4%E8%AF%89%E6%B1%82%22%5D%0A%20%20LEAK%20--%3E%20CHOICE%7B%22%E9%98%B2%E6%B3%84%E6%BC%8F%E8%A3%85%E7%BD%AE%22%7D%0A%20%20CHOICE%20--%3E%7C%E5%85%8D%E8%B4%B9%E9%85%8D%E9%A2%9D%7C%20FREE%5B%22%E7%A7%9F%E9%87%91%E7%95%99%E5%9C%A8%E5%9C%A8%E4%BD%8D%E8%80%85%2C%20%E5%AF%B9%E5%A4%96%E9%9B%B6%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CHOICE%20--%3E%7C%E8%BE%B9%E5%A2%83%E8%B0%83%E8%8A%82%7C%20CBAM%5B%22%E8%BF%9B%E5%8F%A3%E6%8C%89%E5%B5%8C%E5%85%A5%E5%BC%8F%E6%8E%92%E6%94%BE%E4%BB%98%E8%B4%B9%22%5D%0A%20%20CBAM%20--%3E%20CLUB%5B%22%E6%9B%BF%E4%BB%A3%2F%E4%BA%92%E8%A1%A5%3A%20%E7%A2%B3%E4%BF%B1%E4%B9%90%E9%83%A8%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"CBAM 对全球排放为什么强于免费配额：免费配额只保护国内在位者，对外国生产者零信号；CBAM 把碳价第一次写进进口品价格，出口国的产业链被间接定价——政策信号越境，这正是争议的核心：贸易伙伴视其为单边措施，辩护者援引贸易规则的环境例外，最终裁决未出，这本身就是边界的一部分。免费配额为什么必须退场：并存则国内成本与进口成本持续不对称，庇古课还说过免费发放是把租金送在位者。数据为什么先行：过渡期先申报、后缴费，是把嵌入式排放的核证系统先逼出来——没有 MRV 的边境税只是一张关税表。",-1)),(a(),o(i,null,{default:B(()=>[t(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMP%5B%22%E4%B8%80%E6%89%B9%E8%BF%9B%E5%8F%A3%E9%92%A2%E5%88%B0%E5%8F%A3%E5%B2%B8%22%5D%20--%3E%20MEA%5B%22%E6%A0%B8%E7%AE%97%E5%B5%8C%E5%85%A5%E5%BC%8F%E6%8E%92%E6%94%BE%EF%BC%9A%E7%94%B3%E6%8A%A5%E6%88%96%E9%BB%98%E8%AE%A4%E5%80%BC%22%5D%0A%20%20MEA%20--%3E%20CERT%5B%22%E6%8C%89%E5%9B%BD%E5%86%85%E7%A2%B3%E4%BB%B7%E6%8B%8D%E5%8D%96%E5%9D%87%E4%BB%B7%E8%B4%AD%E4%B9%B0%E8%AF%81%E4%B9%A6%22%5D%0A%20%20CERT%20--%3E%20DED%5B%22%E5%8E%9F%E4%BA%A7%E5%9C%B0%E5%B7%B2%E4%BB%98%E7%9A%84%E7%A2%B3%E4%BB%B7%E5%8F%AF%E6%8A%B5%E6%89%A3%22%5D%0A%20%20DED%20--%3E%20SIG%5B%22%E7%A2%B3%E4%BB%B7%E4%BF%A1%E5%8F%B7%E9%9A%8F%E8%B4%A7%E7%89%A9%E8%B6%8A%E5%A2%83%EF%BC%9A%E5%87%BA%E5%8F%A3%E9%93%BE%E8%A2%AB%E9%97%B4%E6%8E%A5%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20ALT%5B%22%E5%85%8D%E8%B4%B9%E9%85%8D%E9%A2%9D%E8%B7%AF%E7%BA%BF%22%5D%20--%3E%20RENT%5B%22%E7%A7%9F%E9%87%91%E7%95%99%E5%9C%A8%E5%9B%BD%E5%86%85%E5%9C%A8%E4%BD%8D%E8%80%85%EF%BC%8C%E5%A4%96%E5%9B%BD%E7%94%9F%E4%BA%A7%E8%80%85%E9%9B%B6%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20SIG%20--%3E%20EXIT%5B%22%E4%B8%A4%E5%A5%97%E8%A3%85%E7%BD%AE%E5%B9%B6%E5%AD%98%20%3D%20%E5%8F%8C%E9%87%8D%E4%BF%9D%E6%8A%A4%20%E2%86%92%20%E5%85%8D%E8%B4%B9%E9%85%8D%E9%A2%9D%E5%BF%85%E9%A1%BB%E9%80%80%E5%9D%A1%22%5D%0A%20%20RENT%20--%3E%20EXIT%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">直觉类比：碳泄漏像捏气球的一端，气鼓到另一端——本地排放降了，全球总量没动，只是生产搬了家。CBAM 想做的是让另一头也受压：碳价跟着货物过境，在哪生产都躲不开这笔成本，气球两头一起被捏住。</span></p><p><span class="marginnote">EU 的 CBAM：2023 年 10 月进入过渡期（只申报），2026 年起正式征收，同期免费配额线性退坡——顺序不能反：先有嵌入式排放的数据系统，再谈收钱。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>默认值定得粗惩罚低碳出口国、定得细纵容造假，粗细是分摊争议的技术面具。「共同但有区别的责任」的公平争议没有消失：碳密集出口多是发展中国家，边境成本落在谁的产业链上要明说。下游与间接排放覆盖不足，留下资源转运与轻加工改税目的规避通道。历史泄漏的实证幅度比口号温和（证据口径见 <a href="/econ/ca-env-policy-evidence">环境政策的实证证据</a>），CBAM 是预防性装置而非补救装置；把预防说成已发生的损害，是政策辩论里最常见的偷换。</p><p><span class="marginnote">常见误区：把 CBAM 读成「已经治好碳泄漏的关税」。实证口径下历史泄漏幅度比口号温和，CBAM 是面向未来的预防装置；把「预防」说成「已补救的损害」，等于把还没发生的账记在它头上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>泄漏有三条通道：生产迁移、能源市场、投资选址；幅度常被夸大，通道是实的。</li><li>CBAM 按嵌入式排放收费、锚定国内碳价、可抵扣原产地碳价；与免费配额并存即双重保护。</li><li>免费配额对外零信号，CBAM 把碳价写进进口价——信号越境既是价值也是争议。</li><li>设计轴三问：排放怎么测、下游覆不覆盖、出口退不退。</li><li>碳俱乐部用贸易结构改变参与激励，是口岸机制的组织化替代。</li><li>出处：Nordhaus 2015；EU CBAM 条例（2023/956）口径；实证幅度见环境政策证据课。</li></ul>',7))])}const f=l(D,[["render",d]]);export{_ as __pageData,f as default};
